{"path": "robot_name.py", "content": "import random
import string


class Robot:
    _used_names = set()

    def __init__(self):
        self._name = None
        self.name  # generate name on first boot

    @property
    def name(self):
        if self._name is None:
            self._name = self._generate_unique_name()
        return self._name

    @classmethod
    def _generate_unique_name(cls):
        if len(cls._used_names) >= 26 * 26 * 1000:
            raise RuntimeError("No unique robot names left")
        while True:
            candidate = "".join(random.choices(string.ascii_uppercase, k=2)) + "".join(
                random.choices(string.digits, k=3)
            )
            if candidate not in cls._used_names:
                cls._used_names.add(candidate)
                return candidate

    def reset(self):
        old = self._name
        self._name = None
        new = self.name
        if old is not None:
            Robot._used_names.discard(old)
        return new
